#include <iostream>
#include <cstring>
#include <queue>
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

const int MAX_NODES = 202;
const int INF = 0x3f3f3f3f;

int edge_flow[MAX_NODES][MAX_NODES], edge_capacity[MAX_NODES][MAX_NODES];
int parent_arr[MAX_NODES], q_arr[MAX_NODES], dist_arr[MAX_NODES];

int computeMaxFlow(int numNodes, int src, int dest) {
    while (true) {
        memset(parent_arr, -1, sizeof(parent_arr));
        dist_arr[src] = INF;
        int qhead = 0, qtail = 0;
        q_arr[qtail++] = src;
        while (qhead < qtail && parent_arr[dest] < 0) {
            int curr = q_arr[qhead++];
            for (int next = 0; next < numNodes; ++next) {
                if (parent_arr[next] < 0) {
                    int residual = edge_capacity[curr][next] - edge_flow[curr][next];
                    if (residual > 0) {
                        parent_arr[q_arr[qtail++] = next] = curr;
                        dist_arr[next] = min(dist_arr[curr], residual);
                    }
                }
            }
        }
        if (parent_arr[dest] < 0) break;
        int flow_push = dist_arr[dest];
        for (int nd = dest; nd != src; nd = parent_arr[nd]) {
            edge_flow[parent_arr[nd]][nd] += flow_push;
            edge_flow[nd][parent_arr[nd]] -= flow_push;
        }
    }
    int total = 0;
    for (int nd = 0; nd < numNodes; ++nd)
        total += edge_flow[src][nd];
    return total;
}

char input_grid[11][11], output_grid[11][11];
int zombie_x, zombie_y, drow[4] = {0, 0, 1, -1}, dcol[4] = {1, -1, 0, 0};
int dist_map[101][101];
int gridSize, timeBound;
vector<int> outRows, outCols;

void runBFS(int sx, int sy, int* resultDist, bool requiresCheck) {
    queue<pair<int, int>> q;
    resultDist[sx * gridSize + sy] = 0;
    q.push({sx, sy});
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        int idx = r * gridSize + c;
        int d = resultDist[idx];
        if (requiresCheck) {
            if (dist_map[zombie_x * gridSize + zombie_y][idx] <= d || timeBound <= d) {
                if (dist_map[zombie_x * gridSize + zombie_y][idx] < d || timeBound < d)
                    resultDist[idx] = INF + 1;
                continue;
            }
        }
        for (int k = 0; k < 4; ++k) {
            int nr = r + drow[k], nc = c + dcol[k];
            if (nr < 0 || nc < 0 || nr == gridSize || nc == gridSize) continue;
            char ch = output_grid[nr][nc];
            if (ch < '0' || ch > '9') continue;
            int nidx = nr * gridSize + nc;
            if (resultDist[nidx] != INF) continue;
            resultDist[nidx] = d + 1;
            q.push({nr, nc});
        }
    }
}

void constructNetwork() {
    for (int i = 0; i < gridSize; ++i) {
        for (int j = 0; j < gridSize; ++j) {
            char val = output_grid[i][j];
            if (val >= '1' && val <= '9') {
                outRows.push_back(i);
                outCols.push_back(j);
                int idx = i * gridSize + j;
                edge_capacity[idx + 2 + gridSize * gridSize][1] = val - '0';
            }
        }
    }
    int zIdx = zombie_x * gridSize + zombie_y;
    for (int i = 0; i < gridSize; ++i) {
        for (int j = 0; j < gridSize; ++j) {
            char val = input_grid[i][j];
            if (val >= '1' && val <= '9') {
                int idx = i * gridSize + j;
                edge_capacity[0][idx + 2] = val - '0';
                for (int k = 0; k < outRows.size(); ++k) {
                    int r = outRows[k], c = outCols[k];
                    int qIdx = r * gridSize + c;
                    if (dist_map[idx][qIdx] < INF)
                        edge_capacity[idx + 2][qIdx + 2 + gridSize * gridSize] = INF;
                }
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> gridSize >> timeBound;
    memset(dist_map, 0x3f, sizeof(dist_map));
    for (int i = 0; i < gridSize; ++i) cin >> input_grid[i];
    for (int i = 0; i < gridSize; ++i) cin >> output_grid[i];
    for (int i = 0; i < gridSize; ++i) {
        for (int j = 0; j < gridSize; ++j) {
            if (input_grid[i][j] == 'Z') {
                zombie_x = i;
                zombie_y = j;
            }
        }
    }
    runBFS(zombie_x, zombie_y, dist_map[zombie_x * gridSize + zombie_y], false);
    for (int i = 0; i < gridSize; ++i) {
        for (int j = 0; j < gridSize; ++j) {
            if (input_grid[i][j] >= '1' && input_grid[i][j] <= '9')
                runBFS(i, j, dist_map[i * gridSize + j], true);
        }
    }
    constructNetwork();
    cout << computeMaxFlow(2 + gridSize * gridSize + gridSize * gridSize, 0, 1) << '\n';
    return 0;
}
